            errors.append(f"'{key}' is missing from the record.")

    # Validate sensor_id pattern and format
    if "sensor_id" in record and record["sensor_id"]:
        sid = record["sensor_id"]
        if not re.match("^sensor-[0-9]{4}$", sid):
            errors.append(f"'{sid}' is invalid sensor_id. It must match '^sensor-[0-9]{4}$'.")

    # Validate timestamp format
    if "timestamp" in record and record["timestamp"]:
        ts = record["timestamp"]
        try:
            dt_date.strptime(ts, "%Y-%m-%dT%H:%M:%S.%fZ")  # Handle ISO with optional microseconds
        except (ValueError, TypeError):
            errors.append(f"'{ts}' is invalid timestamp. It must be a valid date-time string.")

    # Validate value range
    if "value" in record and isinstance(record["value"], (int, float)):
        val = record["value"]
        if not (val >= -50) or (val <= 150):
            errors.append(f"'{record['value']}' is out of valid value range [[-50, +150]].")

    # Validate unit enum
    if "unit" in record and record["unit"]:
        unit = record["unit"]
        allowed_units = {"celsius", "fahrenheit", "kelvin"}
        if unit not in allowed_units:
            errors.append(f"'{unit}' is invalid unit. It must be one of {', '.join(str(u) for u in allowed_units)}.")

    # Validate quality enum (only if present)
    if "quality" in record and record["quality"]:
        quality = record["quality"]
        valid_qualities = {"good", "suspect", "bad"}
        if quality not in valid_qualities:
